#!/usr / bin / env python3\n\"\"\"\n⚡ System Performance Benchmark Tool\n\nSpecialized tool for comprehensive system performance benchmarking.\nMoved from scripts / benchmark_progress.py and enhanced with standardized interfaces.\n\nThis tool provides:\n- ETL pipeline throughput measurement\n- Database query performance testing\n- API response time benchmarking\n- Memory usage and resource consumption monitoring\n- Statistical analysis with control limits and anomaly detection\n\nUsage:\n    python tools / specialized / benchmarking / system_benchmark_tool.py --etl-benchmark\n    python tools / specialized / benchmarking / system_benchmark_tool.py --database-benchmark\n    python tools / specialized / benchmarking / system_benchmark_tool.py --full-system-benchmark\n\"\"\"\n\nimport argparse\nimport json\nimport sys\nimport time\nfrom datetime import datetime, timedelta\nfrom pathlib import Path\nfrom typing import Any, Dict, List, Optional\n\nimport numpy as np\nimport pandas as pd\n\n# Add project root to path\nproject_root = Path(__file__).parent.parent.parent\nsys.path.insert(0, str(project_root))\nsys.path.insert(0, str(project_root / \"src\"))\n\nfrom tools.shared.common import (\n    ToolBase,\n    ToolConfig,\n    register_tool,\n)\n\n# Import system benchmark functionality\ntry:\n    from web.etl_helpers import get_engine\n    from youtubeviz.data import benchmark_run_artist_metrics_pipeline\n    SYSTEM_BENCHMARK_AVAILABLE = True\nexcept ImportError as e:\n    print(f\"⚠️  System benchmark dependencies not available: {e}\")\n    SYSTEM_BENCHMARK_AVAILABLE = False\n\n# Import benchmark progress functionality\ntry:\n    sys.path.insert(0, \"scripts\")\n    from benchmark_progress import METRIC_SPEC, _fd_binned_mode\n    PROGRESS_TRACKING_AVAILABLE = True\nexcept ImportError:\n    PROGRESS_TRACKING_AVAILABLE = False\n    METRIC_SPEC = {}\n\n\nclass SystemBenchmarkTool(ToolBase):\n    \"\"\"\n    Specialized tool for system performance benchmarking.\n    \n    Provides comprehensive system performance testing including:\n    - ETL pipeline throughput and performance\n    - Database query optimization and response times\n    - API performance and rate limiting\n    - Resource usage monitoring and optimization\n    \"\"\"\n\n    def __init__(self):\n        super().__init__(name=\"system-benchmark\", version=\"1.0.0\")\n        \n        # Register this tool in the global registry\n        register_tool(self.get_tool_config())\n        \n        # Performance thresholds and configuration\n        self.performance_thresholds = {\n            \"etl_throughput_rows_per_sec\": {\"good\": 1000, \"acceptable\": 500, \"poor\": 100},\n            \"database_avg_query_time_ms\": {\"good\": 100, \"acceptable\": 500, \"poor\": 2000},\n            \"api_response_time_ms\": {\"good\": 200, \"acceptable\": 1000, \"poor\": 5000},\n            \"memory_usage_mb\": {\"good\": 512, \"acceptable\": 1024, \"poor\": 2048},\n        }\n        \n        # Statistical control limits\n        self.sigma_z_thresh = 3.0  # 3σ control limit\n        self.robust_z_thresh = 3.0  # MAD-based z-score threshold\n        self.iqr_k = 1.5  # Tukey's inner fences\n\n    def get_required_environment_vars(self) -> List[str]:\n        \"\"\"Return list of required environment variables.\"\"\"\n        return [\n            \"DATABASE_URL\",  # For database performance testing\n        ]\n\n    def get_tool_config(self) -> ToolConfig:\n        \"\"\"Return tool configuration metadata.\"\"\"\n        return ToolConfig(\n            name=\"system-benchmark\",\n            version=\"1.0.0\",\n            description=\"Specialized system performance benchmarking tool for ETL, database, and API testing\",\n            dependencies=[\n                \"python>=3.8\",\n                \"pandas>=2.0\",\n                \"numpy>=1.20\",\n                \"sqlalchemy>=2.0\",\n                \"psutil>=5.8\",  # For system resource monitoring\n            ],\n            environment_vars=self.get_required_environment_vars(),\n            usage_examples=[\n                \"python tools / specialized / benchmarking / system_benchmark_tool.py --etl-benchmark\",\n                \"python tools / specialized / benchmarking / system_benchmark_tool.py --database-benchmark\",\n                \"python tools / specialized / benchmarking / system_benchmark_tool.py --full-system-benchmark\",\n            ],\n            category=\"specialized\"\n        )\n\n    def run(self) -> None:\n        \"\"\"Main execution method-should not be called directly.\"\"\"\n        self.log_progress(\"Use specific methods like run_etl_benchmark() or run_database_benchmark()\")\n\n    def run_etl_benchmark(self, config: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:\n        \"\"\"\n        Run ETL pipeline performance benchmark.\n        \n        Args:\n            config: Optional configuration for ETL benchmarking\n            \n        Returns:\n            Dictionary with ETL benchmark results\n        \"\"\"\n        self.log_progress(\"🚀 Starting ETL performance benchmark\")\n        \n        if not SYSTEM_BENCHMARK_AVAILABLE:\n            return {\n                \"status\": \"ERROR\",\n                \"error\": \"ETL benchmark dependencies not available\",\n            }\n        \n        try:\n            # Default configuration\n            benchmark_config = {\n                \"iterations\": config.get(\"iterations\", 3) if config else 3,\n                \"measure_memory\": config.get(\"measure_memory\", True) if config else True,\n                \"detailed_timing\": config.get(\"detailed_timing\", True) if config else True,\n            }\n            \n            self.log_progress(f\"Running ETL benchmark with {benchmark_config['iterations']} iterations\")\n            \n            # Measure system resources before\n            initial_memory = self._get_memory_usage() if benchmark_config[\"measure_memory\"] else 0\n            \n            # Run the ETL benchmark\n            start_time = time.time()\n            \n            try:\n                etl_results = benchmark_run_artist_metrics_pipeline(\n                    iterations=benchmark_config[\"iterations\"]\n                )\n            except Exception as e:\n                # Fallback to basic ETL timing if the function is not available\n                self.log_progress(f\"⚠️  Advanced ETL benchmark not available, using basic timing: {e}\")\n                etl_results = self._run_basic_etl_benchmark(benchmark_config[\"iterations\"])\n            \n            end_time = time.time()\n            total_time = end_time-start_time\n            \n            # Measure system resources after\n            final_memory = self._get_memory_usage() if benchmark_config[\"measure_memory\"] else 0\n            memory_delta = final_memory-initial_memory\n            \n            # Calculate performance metrics\n            throughput = etl_results.get(\"throughput_rows_per_sec\", 0)\n            total_rows = etl_results.get(\"total_rows_processed\", 0)\n            \n            # Determine performance level\n            performance_level = self._evaluate_performance(\n                \"etl_throughput_rows_per_sec\", throughput\n            )\n            \n            results = {\n                \"status\": \"SUCCESS\",\n                \"timestamp\": datetime.now().isoformat(),\n                \"config\": benchmark_config,\n                \"metrics\": {\n                    \"throughput_rows_per_sec\": throughput,\n                    \"total_time_seconds\": total_time,\n                    \"total_rows_processed\": total_rows,\n                    \"avg_time_per_iteration\": total_time / benchmark_config[\"iterations\"],\n                    \"memory_usage_delta_mb\": memory_delta,\n                    \"initial_memory_mb\": initial_memory,\n                    \"final_memory_mb\": final_memory,\n                },\n                \"performance\": {\n                    \"level\": performance_level,\n                    \"score\": self._calculate_etl_score(throughput, total_time, memory_delta),\n                },\n                \"raw_results\": etl_results,\n            }\n            \n            self.log_progress(f\"✅ ETL benchmark completed: {throughput:.1f} rows / sec ({performance_level})\")\n            return results\n            \n        except Exception as e:\n            self.handle_error(e, \"ETL benchmarking\")\n            return {\n                \"status\": \"ERROR\",\n                \"error\": str(e),\n            }\n\n    def run_database_benchmark(self, config: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:\n        \"\"\"\n        Run database performance benchmark.\n        \n        Args:\n            config: Optional configuration for database benchmarking\n            \n        Returns:\n            Dictionary with database benchmark results\n        \"\"\"\n        self.log_progress(\"🗄️  Starting database performance benchmark\")\n        \n        try:\n            # Default configuration\n            benchmark_config = {\n                \"query_iterations\": config.get(\"query_iterations\", 5) if config else 5,\n                \"include_complex_queries\": config.get(\"include_complex_queries\", True) if config else True,\n                \"measure_connection_time\": config.get(\"measure_connection_time\", True) if config else True,\n            }\n            \n            engine = get_engine()\n            \n            # Test queries with different complexity levels\n            test_queries = [\n                {\n                    \"name\": \"simple_count\",\n                    \"query\": \"SELECT COUNT(*) FROM youtube_videos\",\n                    \"description\": \"Simple count query\",\n                },\n                {\n                    \"name\": \"filtered_count\",\n                    \"query\": \"SELECT COUNT(*) FROM youtube_comments WHERE like_count > 10\",\n                    \"description\": \"Filtered count with WHERE clause\",\n                },\n                {\n                    \"name\": \"group_by_artist\",\n                    \"query\": \"SELECT channel_title, COUNT(*) as video_count FROM youtube_videos GROUP BY channel_title LIMIT 10\",\n                    \"description\": \"GROUP BY query with aggregation\",\n                },\n            ]\n            \n            if benchmark_config[\"include_complex_queries\"]:\n                test_queries.extend([\n                    {\n                        \"name\": \"join_query\",\n                        \"query\": \"\"\"\n                        SELECT v.channel_title, COUNT(c.comment_id) as comment_count\n                        FROM youtube_videos v\n                        LEFT JOIN youtube_comments c ON v.video_id = c.video_id\n                        GROUP BY v.channel_title\n                        LIMIT 10\n                        \"\"\",\n                        \"description\": \"JOIN query with aggregation\",\n                    },\n                    {\n                        \"name\": \"complex_analytics\",\n                        \"query\": \"\"\"\n                        SELECT \n                            channel_title,\n                            AVG(view_count) as avg_views,\n                            MAX(like_count) as max_likes,\n                            COUNT(*) as video_count\n                        FROM youtube_videos\n                        WHERE published_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)\n                        GROUP BY channel_title\n                        HAVING video_count > 1\n                        ORDER BY avg_views DESC\n                        LIMIT 5\n                        \"\"\",\n                        \"description\": \"Complex analytics query\",\n                    },\n                ])\n            \n            query_results = []\n            total_query_time = 0\n            \n            # Run each query multiple times\n            for query_info in test_queries:\n                query_times = []\n                \n                for iteration in range(benchmark_config[\"query_iterations\"]):\n                    try:\n                        # Measure connection time if requested\n                        if benchmark_config[\"measure_connection_time\"]:\n                            conn_start = time.time()\n                            conn = engine.connect()\n                            conn_time = time.time() - conn_start\n                        else:\n                            conn = engine.connect()\n                            conn_time = 0\n                        \n                        # Execute query\n                        query_start = time.time()\n                        result = conn.execute(query_info[\"query\"])\n                        rows = result.fetchall()\n                        query_end = time.time()\n                        \n                        query_time = query_end-query_start\n                        query_times.append(query_time)\n                        total_query_time += query_time\n                        \n                        conn.close()\n                        \n                    except Exception as e:\n                        self.log_progress(f\"⚠️  Query failed: {query_info['name']} - {e}\")\n                        query_times.append(float('inf'))\n                \n                # Calculate statistics for this query\n                valid_times = [t for t in query_times if t != float('inf')]\n                if valid_times:\n                    query_result = {\n                        \"name\": query_info[\"name\"],\n                        \"description\": query_info[\"description\"],\n                        \"avg_time_seconds\": np.mean(valid_times),\n                        \"min_time_seconds\": np.min(valid_times),\n                        \"max_time_seconds\": np.max(valid_times),\n                        \"std_time_seconds\": np.std(valid_times),\n                        \"iterations\": len(valid_times),\n                        \"success_rate\": len(valid_times) / benchmark_config[\"query_iterations\"],\n                    }\n                else:\n                    query_result = {\n                        \"name\": query_info[\"name\"],\n                        \"description\": query_info[\"description\"],\n                        \"avg_time_seconds\": float('inf'),\n                        \"success_rate\": 0.0,\n                        \"error\": \"All queries failed\",\n                    }\n                \n                query_results.append(query_result)\n            \n            # Calculate overall metrics\n            successful_queries = [q for q in query_results if q.get(\"success_rate\", 0) > 0]\n            if successful_queries:\n                avg_query_time = np.mean([q[\"avg_time_seconds\"] for q in successful_queries])\n                performance_level = self._evaluate_performance(\n                    \"database_avg_query_time_ms\", avg_query_time * 1000\n                )\n            else:\n                avg_query_time = float('inf')\n                performance_level = \"poor\"\n            \n            results = {\n                \"status\": \"SUCCESS\",\n                \"timestamp\": datetime.now().isoformat(),\n                \"config\": benchmark_config,\n                \"metrics\": {\n                    \"avg_query_time_seconds\": avg_query_time,\n                    \"total_query_time_seconds\": total_query_time,\n                    \"total_queries_executed\": len(test_queries) * benchmark_config[\"query_iterations\"],\n                    \"successful_queries\": len(successful_queries),\n                    \"query_success_rate\": len(successful_queries) / len(test_queries),\n                },\n                \"performance\": {\n                    \"level\": performance_level,\n                    \"score\": self._calculate_database_score(avg_query_time, len(successful_queries), len(test_queries)),\n                },\n                \"query_details\": query_results,\n            }\n            \n            self.log_progress(f\"✅ Database benchmark completed: {avg_query_time * 1000:.1f}ms avg ({performance_level})\")\n            return results\n            \n        except Exception as e:\n            self.handle_error(e, \"database benchmarking\")\n            return {\n                \"status\": \"ERROR\",\n                \"error\": str(e),\n            }\n\n    def run_full_system_benchmark(self, config: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:\n        \"\"\"\n        Run comprehensive system performance benchmark.\n        \n        Args:\n            config: Optional configuration for full system benchmarking\n            \n        Returns:\n            Dictionary with complete system benchmark results\n        \"\"\"\n        self.log_progress(\"🚀 Starting full system performance benchmark\")\n        \n        try:\n            full_results = {\n                \"timestamp\": datetime.now().isoformat(),\n                \"benchmark_type\": \"full_system\",\n                \"results\": {},\n                \"summary\": {},\n            }\n            \n            # Run ETL benchmark\n            self.log_progress(\"Running ETL performance benchmark...\")\n            etl_results = self.run_etl_benchmark(config)\n            full_results[\"results\"][\"etl\"] = etl_results\n            \n            # Run database benchmark\n            self.log_progress(\"Running database performance benchmark...\")\n            db_results = self.run_database_benchmark(config)\n            full_results[\"results\"][\"database\"] = db_results\n            \n            # Calculate overall system score\n            system_scores = []\n            \n            if etl_results.get(\"status\") == \"SUCCESS\":\n                system_scores.append(etl_results[\"performance\"][\"score\"])\n            \n            if db_results.get(\"status\") == \"SUCCESS\":\n                system_scores.append(db_results[\"performance\"][\"score\"])\n            \n            overall_score = np.mean(system_scores) if system_scores else 0.0\n            overall_level = self._score_to_level(overall_score)\n            \n            # Generate summary\n            full_results[\"summary\"] = {\n                \"overall_score\": overall_score,\n                \"overall_level\": overall_level,\n                \"components_tested\": len(full_results[\"results\"]),\n                \"successful_components\": len([r for r in full_results[\"results\"].values() if r.get(\"status\") == \"SUCCESS\"]),\n                \"recommendations\": self._generate_performance_recommendations(full_results[\"results\"]),\n            }\n            \n            self.log_progress(f\"✅ Full system benchmark completed: {overall_score:.2f} ({overall_level})\")\n            return full_results\n            \n        except Exception as e:\n            self.handle_error(e, \"full system benchmarking\")\n            return {\n                \"status\": \"ERROR\",\n                \"error\": str(e),\n            }\n\n    def _run_basic_etl_benchmark(self, iterations: int) -> Dict[str, Any]:\n        \"\"\"Fallback basic ETL benchmark if advanced benchmarking is not available.\"\"\"\n        try:\n            engine = get_engine()\n            \n            total_rows = 0\n            start_time = time.time()\n            \n            for i in range(iterations):\n                # Simple query to simulate ETL work\n                with engine.connect() as conn:\n                    result = conn.execute(\"SELECT COUNT(*) FROM youtube_videos\")\n                    count = result.scalar()\n                    total_rows += count\n            \n            end_time = time.time()\n            total_time = end_time-start_time\n            \n            return {\n                \"throughput_rows_per_sec\": total_rows / total_time if total_time > 0 else 0,\n                \"total_rows_processed\": total_rows,\n                \"total_time_seconds\": total_time,\n                \"method\": \"basic_fallback\",\n            }\n            \n        except Exception as e:\n            return {\n                \"throughput_rows_per_sec\": 0,\n                \"total_rows_processed\": 0,\n                \"error\": str(e),\n                \"method\": \"basic_fallback_failed\",\n            }\n\n    def _get_memory_usage(self) -> float:\n        \"\"\"Get current memory usage in MB.\"\"\"\n        try:\n            import psutil\n            process = psutil.Process()\n            return process.memory_info().rss / 1024 / 1024  # Convert to MB\n        except ImportError:\n            return 0.0\n        except Exception:\n            return 0.0\n\n    def _evaluate_performance(self, metric_name: str, value: float) -> str:\n        \"\"\"Evaluate performance level based on thresholds.\"\"\"\n        if metric_name not in self.performance_thresholds:\n            return \"unknown\"\n        \n        thresholds = self.performance_thresholds[metric_name]\n        \n        # For metrics where lower is better (like query time)\n        if \"time\" in metric_name.lower():\n            if value <= thresholds[\"good\"]:\n                return \"excellent\"\n            elif value <= thresholds[\"acceptable\"]:\n                return \"good\"\n            elif value <= thresholds[\"poor\"]:\n                return \"acceptable\"\n            else:\n                return \"poor\"\n        \n        # For metrics where higher is better (like throughput)\n        else:\n            if value >= thresholds[\"good\"]:\n                return \"excellent\"\n            elif value >= thresholds[\"acceptable\"]:\n                return \"good\"\n            elif value >= thresholds[\"poor\"]:\n                return \"acceptable\"\n            else:\n                return \"poor\"\n\n    def _calculate_etl_score(self, throughput: float, total_time: float, memory_delta: float) -> float:\n        \"\"\"Calculate ETL performance score (0-1).\"\"\"\n        # Throughput score (0-1)\n        throughput_score = min(1.0, throughput / 1000)  # 1000 rows / sec = perfect\n        \n        # Time efficiency score (0-1)\n        time_score = max(0.0, 1.0 - (total_time / 300))  # 5 minutes = 0 score\n        \n        # Memory efficiency score (0-1)\n        memory_score = max(0.0, 1.0 - (abs(memory_delta) / 1024))  # 1GB delta = 0 score\n        \n        # Weighted average\n        return (throughput_score * 0.5 + time_score * 0.3 + memory_score * 0.2)\n\n    def _calculate_database_score(self, avg_query_time: float, successful_queries: int, total_queries: int) -> float:\n        \"\"\"Calculate database performance score (0-1).\"\"\"\n        # Query time score (0-1)\n        time_score = max(0.0, 1.0 - (avg_query_time / 5.0))  # 5 seconds = 0 score\n        \n        # Success rate score (0-1)\n        success_score = successful_queries / total_queries if total_queries > 0 else 0.0\n        \n        # Weighted average\n        return (time_score * 0.7 + success_score * 0.3)\n\n    def _score_to_level(self, score: float) -> str:\n        \"\"\"Convert numeric score to performance level.\"\"\"\n        if score >= 0.9:\n            return \"excellent\"\n        elif score >= 0.7:\n            return \"good\"\n        elif score >= 0.5:\n            return \"acceptable\"\n        else:\n            return \"poor\"\n\n    def _generate_performance_recommendations(self, results: Dict[str, Any]) -> List[str]:\n        \"\"\"Generate performance improvement recommendations.\"\"\"\n        recommendations = []\n        \n        # ETL recommendations\n        if \"etl\" in results and results[\"etl\"].get(\"status\") == \"SUCCESS\":\n            etl_perf = results[\"etl\"][\"performance\"]\n            if etl_perf[\"level\"] in [\"poor\", \"acceptable\"]:\n                recommendations.append(\"ETL performance below optimal-consider database indexing and query optimization\")\n                \n                throughput = results[\"etl\"][\"metrics\"].get(\"throughput_rows_per_sec\", 0)\n                if throughput < 500:\n                    recommendations.append(\"ETL throughput very low-investigate database connection pooling and batch processing\")\n        \n        # Database recommendations\n        if \"database\" in results and results[\"database\"].get(\"status\") == \"SUCCESS\":\n            db_perf = results[\"database\"][\"performance\"]\n            if db_perf[\"level\"] in [\"poor\", \"acceptable\"]:\n                recommendations.append(\"Database performance below optimal-review query plans and add missing indexes\")\n                \n                success_rate = results[\"database\"][\"metrics\"].get(\"query_success_rate\", 1.0)\n                if success_rate < 1.0:\n                    recommendations.append(\"Some database queries failing-check database schema and permissions\")\n        \n        if not recommendations:\n            recommendations.append(\"System performance is optimal-no immediate improvements needed\")\n        \n        return recommendations\n\n    def cleanup_resources(self) -> None:\n        \"\"\"Clean up any resources used during benchmarking.\"\"\"\n        # No persistent resources to clean up\n        pass\n\n\ndef main():\n    \"\"\"Main entry point for the system benchmark tool.\"\"\"\n    parser = argparse.ArgumentParser(\n        description=\"System Performance Benchmark Tool\",\n        formatter_class=argparse.RawDescriptionHelpFormatter,\n        epilog=\"\"\"\nExamples:\n  python tools / specialized / benchmarking / system_benchmark_tool.py --etl-benchmark\n  python tools / specialized / benchmarking / system_benchmark_tool.py --database-benchmark\n  python tools / specialized / benchmarking / system_benchmark_tool.py --full-system-benchmark\n        \"\"\",\n    )\n\n    # Operations\n    parser.add_argument(\"--etl-benchmark\", action=\"store_true\", \n                       help=\"Run ETL pipeline performance benchmark\")\n    parser.add_argument(\"--database-benchmark\", action=\"store_true\", \n                       help=\"Run database performance benchmark\")\n    parser.add_argument(\"--full-system-benchmark\", action=\"store_true\", \n                       help=\"Run comprehensive system performance benchmark\")\n\n    # Configuration\n    parser.add_argument(\"--iterations\", type=int, default=3,\n                       help=\"Number of iterations for ETL benchmark\")\n    parser.add_argument(\"--query-iterations\", type=int, default=5,\n                       help=\"Number of iterations for each database query\")\n    parser.add_argument(\"--include-complex-queries\", action=\"store_true\", default=True,\n                       help=\"Include complex queries in database benchmark\")\n    parser.add_argument(\"--verbose\", \"-v\", action=\"store_true\", \n                       help=\"Verbose output\")\n\n    args = parser.parse_args()\n\n    if not SYSTEM_BENCHMARK_AVAILABLE:\n        print(\"❌ System benchmark dependencies not available. Please check database connection.\")\n        return 1\n\n    # Create system benchmark tool instance\n    with SystemBenchmarkTool() as benchmark_tool:\n        try:\n            config = {\n                \"iterations\": args.iterations,\n                \"query_iterations\": args.query_iterations,\n                \"include_complex_queries\": args.include_complex_queries,\n            }\n            \n            if args.etl_benchmark:\n                result = benchmark_tool.run_etl_benchmark(config)\n                if result[\"status\"] == \"SUCCESS\":\n                    metrics = result[\"metrics\"]\n                    perf = result[\"performance\"]\n                    print(f\"⚡ ETL Benchmark Results:\")\n                    print(f\"   Throughput: {metrics['throughput_rows_per_sec']:.1f} rows / sec\")\n                    print(f\"   Total time: {metrics['total_time_seconds']:.2f} seconds\")\n                    print(f\"   Rows processed: {metrics['total_rows_processed']:,}\")\n                    print(f\"   Memory delta: {metrics['memory_usage_delta_mb']:.1f} MB\")\n                    print(f\"   Performance: {perf['level']} (score: {perf['score']:.2f})\")\n                else:\n                    print(f\"❌ ETL benchmark failed: {result.get('error', 'Unknown error')}\")\n                    return 1\n            \n            elif args.database_benchmark:\n                result = benchmark_tool.run_database_benchmark(config)\n                if result[\"status\"] == \"SUCCESS\":\n                    metrics = result[\"metrics\"]\n                    perf = result[\"performance\"]\n                    print(f\"🗄️  Database Benchmark Results:\")\n                    print(f\"   Average query time: {metrics['avg_query_time_seconds']*1000:.1f} ms\")\n                    print(f\"   Total queries: {metrics['total_queries_executed']}\")\n                    print(f\"   Success rate: {metrics['query_success_rate']*100:.1f}%\")\n                    print(f\"   Performance: {perf['level']} (score: {perf['score']:.2f})\")\n                    \n                    print(f\"\\n📊 Query Details:\")\n                    for query in result[\"query_details\"]:\n                        if \"error\" not in query:\n                            print(f\"   {query['name']}: {query['avg_time_seconds']*1000:.1f}ms avg ({query['success_rate']*100:.0f}% success)\")\n                        else:\n                            print(f\"   {query['name']}: FAILED - {query.get('error', 'Unknown error')}\")\n                else:\n                    print(f\"❌ Database benchmark failed: {result.get('error', 'Unknown error')}\")\n                    return 1\n            \n            elif args.full_system_benchmark:\n                result = benchmark_tool.run_full_system_benchmark(config)\n                if result.get(\"status\") != \"ERROR\":\n                    summary = result[\"summary\"]\n                    print(f\"🚀 Full System Benchmark Results:\")\n                    print(f\"   Overall score: {summary['overall_score']:.2f} ({summary['overall_level']})\")\n                    print(f\"   Components tested: {summary['successful_components']}/{summary['components_tested']}\")\n                    \n                    # Show component details\n                    if \"etl\" in result[\"results\"] and result[\"results\"][\"etl\"].get(\"status\") == \"SUCCESS\":\n                        etl_metrics = result[\"results\"][\"etl\"][\"metrics\"]\n                        print(f\"   ETL: {etl_metrics['throughput_rows_per_sec']:.1f} rows / sec\")\n                    \n                    if \"database\" in result[\"results\"] and result[\"results\"][\"database\"].get(\"status\") == \"SUCCESS\":\n                        db_metrics = result[\"results\"][\"database\"][\"metrics\"]\n                        print(f\"   Database: {db_metrics['avg_query_time_seconds']*1000:.1f}ms avg\")\n                    \n                    if summary.get(\"recommendations\"):\n                        print(f\"\\n💡 Recommendations:\")\n                        for rec in summary[\"recommendations\"]:\n                            print(f\"   • {rec}\")\n                else:\n                    print(f\"❌ Full system benchmark failed: {result.get('error', 'Unknown error')}\")\n                    return 1\n            \n            else:\n                print(\"❌ No benchmark type specified. Use --help for options.\")\n                return 1\n            \n            return 0\n\n        except KeyboardInterrupt:\n            benchmark_tool.log_progress(\"System benchmark cancelled by user\")\n            return 1\n        except Exception as e:\n            benchmark_tool.handle_error(e, \"main execution\")\n            return 1\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n"
